#include "unity.h"
#include "header.h"
#include "helpers.h"
#include <stdlib.h>
#include <stdio.h>

void setUp(void) { }
void tearDown(void) { }

void unit_test_kohonen_som_immediate_exit(void) {
    // Setup: Choose inputs that cause the main training loop to exit immediately.
    // Conditions: alpha > alpha_min && dmin > 1e-3 must be false on first check.
    // We set alpha_min >= 1.0 so alpha (1.0) is NOT > alpha_min.
    double alpha_min = 1.0; // alpha starts at 1.0, so condition fails.
    int num_out = 4;
    int num_features = 2;
    int num_samples = 1;

    // Allocate and initialize input data matrix X (1 sample, 2 features)
    double **X = (double **)malloc(num_samples * sizeof(double *));
    X[0] = (double *)malloc(num_features * sizeof(double));
    X[0][0] = 0.5;
    X[0][1] = 0.5;

    // Allocate and initialize weight matrix W (3D array: num_out x num_out x num_features)
    struct kohonen_array_3d *W = (struct kohonen_array_3d *)malloc(sizeof(struct kohonen_array_3d));
    W->dim1 = num_out;
    W->dim2 = num_out;
    W->dim3 = num_features;
    int total_weights = num_out * num_out * num_features;
    W->data = (double *)malloc(total_weights * sizeof(double));
    for (int i = 0; i < total_weights; i++) {
        W->data[i] = 0.1; // Small initial weights
    }

    // Capture stdout to verify the newline is printed
    // We'll use a simple approach: redirect stdout to a file or buffer.
    // Since we don't have the capture_stdout functions in the operation map,
    // we will just call the function and rely on the path's behavior.
    // The path includes putchar('
') and cleanup loops.
    // We'll assert that the function returns without crashing.

    // Test: call kohonen_som
    kohonen_som(X, W, num_samples, num_features, num_out, alpha_min);

    // Assertions: The function should have executed the path:
    // - Allocated D matrix (num_out rows)
    // - Initialized dmin = 1.0
    // - Entered outer loop, condition false (alpha <= alpha_min)
    // - Printed newline (putchar)
    // - Freed D matrix
    // - Returned
    // We can't easily assert the internal behavior, but we can verify
    // that W is still valid (not corrupted) and no crash occurred.
    TEST_ASSERT_NOT_NULL(W);
    TEST_ASSERT_NOT_NULL(W->data);
    // Check a sample weight value is unchanged (since no training occurred)
    TEST_ASSERT_EQUAL_DOUBLE(0.1, W->data[0]);

    // Cleanup
    free(X[0]);
    free(X);
    free(W->data);
    free(W);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_kohonen_som_immediate_exit);
    return UNITY_END();
}

